export function renderPrompt(text, vars) {
  return String(text || "").replace(/\{\{([^{}]+)\}\}/g, (match, key) => {
    const name = key.trim();
    return Object.hasOwn(vars, name) ? String(vars[name]) : match;
  });
}

// 分析提示词的固定开头：讲清工作目录是什么，并给出两步必须照抄的启动命令。
function analysisHeader(distro, wslPath) {
  return [
    "你在给同事写一份操作说明，用途只有一个：让人照着把项目启动起来，并录制一段运行中的屏幕录像。读者对这个项目一无所知，会照着你的步骤一步步做，边做边录。",
    "",
    "当前工作目录里的 project/ 就是这次要录屏的项目的一个完整副本（不含 .git 与 node_modules）。直接用本机的目录列表、读文件、搜索工具查看即可，不要执行任何 wsl 命令，也不要修改这里的文件。只看当前工作目录里的内容，上层目录、平台自身的代码与文档都与此任务无关，不要去读。",
    "",
    "固定不变的步骤，请原样写进说明：",
    IS_WINDOWS ? `1. 在 Windows 上打开 PowerShell，进入 WSL：wsl -d ${distro}` : `1. 在 ${platformInfo().label} 上打开 Terminal。`,
    `2. 进入产物目录：cd '${String(wslPath).replace(/'/g, "'\\''")}'`,
    "",
    "然后按下面的要求继续：",
  ].join("\n");
}

