// 空白模板按默认正文处理，与设置里的空值回退保持一致。
function templateOf(template, fallback) {
  const text = String(template || "").trim();
  return text || fallback;
}

export function buildAnalysisPrompt({ distro, wslPath, template } = {}) {
  const body = renderPrompt(templateOf(template, DEFAULT_ANALYSIS_PROMPT), {
    发行版: IS_WINDOWS ? distro : platformInfo().label,
    产物目录: wslPath,
  });
  return [analysisHeader(distro, wslPath), body, "", naturalStyleRules()].join("\n");
}

