// 结尾固定拼上的程序读取行：结论与环境可复现等级必须能被解析，所以不放进可改文本。
function feedbackOutputRules(conclusionOptions, levelOptions) {
  return [
    "输出要求：",
    `第一行只写结论，格式为“结论：<取值>”，取值只能从这几个里选一个并原样抄写：${conclusionOptions.join("、")}。这一行是程序读取用的，其余内容不要迁就它。`,
    `第二行写环境可复现等级，格式为“环境可复现等级：<取值>”，取值只能从这几个里选一个并原样抄写：${levelOptions.join("、")}。这一行同样是程序读取用的。`,
    "从第三行开始写理由，用普通中文段落，不用 Markdown，不分小标题；等级是怎么定出来的要在理由里交代清楚。",
    "不要输出与本次评估无关的内容，不要写客套话，不要输出思考过程。",
  ].join("\n");
}

export function buildFeedbackPrompt({ conclusionOptions = DEFAULT_CONCLUSION_OPTIONS, levelOptions = DEFAULT_LEVEL_OPTIONS, template } = {}) {  const body = renderPrompt(templateOf(template, DEFAULT_FEEDBACK_PROMPT), {
    结论选项: conclusionOptions.join("、"),
    等级选项: levelOptions.join("、"),
  });
  return [body, "", feedbackOutputRules(conclusionOptions, levelOptions), "", naturalStyleRules()].join("\n");
}

