// 在本机执行运行脚本，检查输出与退出码，供页面展示验证结果。
import fs from "node:fs/promises";
import path from "node:path";
import { spawn } from "node:child_process";
import { isUtf8 } from "node:buffer";
import { decodeFromConsole, encodeForConsole } from "./console-encoding.mjs";
import { IS_WINDOWS, SCRIPT_EXTENSION, nativeEnv } from "./platform.mjs";
import { scriptDirectory, stripPause } from "./scriptrun.mjs";
import { EXECUTION_SIDE } from "./jobs.mjs";
export { stripPause } from "./scriptrun.mjs";

// 单次验证允许跑多久：脚本里有 start 或长驻命令时到这里就收尾，按“还在跑”处理。
// 启动类脚本会 sleep 等待服务就绪，这里给到 3 分钟。
export const SCRIPT_VERIFY_TIMEOUT_MS = 300000;
// 日志保留多少字符，够定位问题就行。
const LOG_LIMIT = 4000;

// cmd 自己报出来的错：命令找不到、路径找不到、批处理语法错误、显式的 errorlevel 分支。
const ERROR_PATTERNS = [
  /is not recognized as an internal or external command/i,
  /不是内部或外部命令/,
  /系统找不到指定的路径/,
  /系统找不到指定的文件/,
  /The system cannot find the path specified/i,
  /The system cannot find the file specified/i,
  /was unexpected at this time/i,
  /命令语法不正确/,
  /\[错误\]/,
  /^ERROR[:：]/im,
  /command not found/i,
  /syntax error near unexpected token/i,
  /Permission denied/i,
  /No such file or directory/i,
  /Wsl\/\S*(?:WSL_E_|ERROR_)/i,
];

export function decodeScriptOutput(chunk) {
  const bytes = Buffer.from(chunk);
  const nuls = bytes.reduce((count, byte) => count + Number(byte === 0), 0);
  if (nuls > bytes.length / 4) return bytes.toString('utf16le');
  return isUtf8(bytes) ? bytes.toString('utf8') : decodeFromConsole(bytes);
}

// 只看命令输出行，跳过脚本自己打的说明与分隔线（run 命令第一行带上标记，后面用它定位）。
function commandOutput(stdout) {
  const lines = String(stdout || "").split(/\r?\n/);
  const start = lines.findIndex((line) => line.includes("__FEEDBACK_SCRIPT_VERIFY_START__"));
  return (start >= 0 ? lines.slice(start + 1) : lines).join("\n");
}

export function analyzeScriptRun({ code, timedOut, stdout, stderr }) {
  const output = commandOutput(stdout);
  const combined = `${output}\n${stderr || ""}`;
  const matched = ERROR_PATTERNS.find((pattern) => pattern.test(combined));
  const problems = [];
  if (matched) problems.push(`输出里有报错：${combined.split(/\r?\n/).find((line) => matched.test(line))?.trim().slice(0, 200) || matched.source}`);
  if (!timedOut && code !== 0) problems.push(`退出码是 ${code}`);
  const ok = problems.length === 0;
  return {
    ok,
    error: ok ? null : problems.join("；"),
    output: combined.trim().slice(-LOG_LIMIT),
  };
}

// 把输出收下来：cmd /c 跑完就结束，脚本里的 start 与后台命令不会拖住这里。
// 输出按当前代码页解成文本，否则中文报错在平台这边是乱码。
export function runScriptForVerify({ scriptPath, timeoutMs = SCRIPT_VERIFY_TIMEOUT_MS }) {
  return new Promise((resolve, reject) => {
    const child = spawn(IS_WINDOWS ? "cmd.exe" : "/bin/bash", IS_WINDOWS ? ["/d", "/c", scriptPath] : [scriptPath], {
      cwd: path.dirname(scriptPath), windowsHide: true, detached: !IS_WINDOWS,
      env: { ...process.env, ...(!IS_WINDOWS ? nativeEnv() : {}), FEEDBACK_SCRIPT_VERIFY: "1" },
    });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let forceTimer;
    const terminateGroup = (signal) => {
      try { process.kill(-child.pid, signal); }
      catch (error) { if (error.code !== "ESRCH") throw error; }
    };
    const timer = setTimeout(() => {
      timedOut = true;
      if (IS_WINDOWS) child.kill();
      else {
        terminateGroup("SIGTERM");
        forceTimer = setTimeout(() => terminateGroup("SIGKILL"), 2000);
      }
    }, timeoutMs);
    child.stdin.end();
    child.stdout.on("data", (chunk) => {
      stdout += decodeScriptOutput(chunk);
      if (stdout.length > 200000) stdout = stdout.slice(-100000);
    });
    child.stderr.on("data", (chunk) => {
      stderr += decodeScriptOutput(chunk);
      if (stderr.length > 50000) stderr = stderr.slice(-25000);
    });
    child.on("error", (error) => {
      clearTimeout(timer);
      clearTimeout(forceTimer);
      reject(error);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      clearTimeout(forceTimer);
      if (!IS_WINDOWS && timedOut) terminateGroup("SIGKILL");
      resolve(analyzeScriptRun({ code: code ?? 1, timedOut, stdout, stderr }));
    });
  });
}

export function buildVerifyScript(text) {
  if (!IS_WINDOWS) return `${String(text || "").replace(/\r\n/g, "\n").trim()}\n`;
  const lines = stripPause(text).split(/\r?\n/);
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
  return `${lines.join("\r\n")}\r\n`;
}

export async function writeVerifyCopy(uid, side, text) {
  if (side !== EXECUTION_SIDE) throw new Error('本期只支持当前执行脚本验证');
  const target = path.join(scriptDirectory(uid), `${side}-run.verify${SCRIPT_EXTENSION}`);
  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.writeFile(target, encodeForConsole(buildVerifyScript(text)));
  return target;
}

export async function removeVerifyCopy(uid, side) {
  if (side !== EXECUTION_SIDE) throw new Error('本期只支持当前执行脚本验证');
  await fs.rm(path.join(scriptDirectory(uid), `${side}-run.verify${SCRIPT_EXTENSION}`), { force: true });
}

